'use strict';
// Sound: ambient beds that crossfade, layered soundscapes (js/soundscapes.js), one-shots, voice lines,
// and the body as a mixer.
// A fixed pool of audio elements, reused. Browsers cap media players per page (~75),
// so creating one per sound would silence the game after a few hundred scenes.
// Loudness: js/levels.js (generated by scripts/levels.py) gives each file a gain so the beds match.
// Loops: the beds play in Web Audio as decoded buffers that loop sample-exactly between the points
// scripts/gen_sfx.py made seamless (LOOPS in js/levels.js), so there is no gap at the loop whatever the
// browser's MP3 decoder does with the encoder's padding. Without Web Audio (file://) they fall back to
// a looping media element, as before.
const AUDIO = (() => {
  const web = location.protocol !== 'file:' && window.AudioContext; // file:// cannot fetch or route media through Web Audio
  let ctx = null, lowpass = null, routed = false;
  let on = true;
  try { on = localStorage.getItem('ten-years-sound') !== 'off'; } catch (e) {}
  // test pages are silent unless the link asks for sound (&sound); nothing here touches the player's setting
  let testing = typeof STORE !== 'undefined' && STORE.mode() === 'test';
  if (testing) on = /[?&]sound\b/.test(location.search);
  const missing = {};
  const AMB_VOL = 0.5, SFX_VOL = 0.85, VOICE_VOL = 0.95;
  const AMB_IN = 3600, AMB_OUT = 2600;                 // ms
  // one-shots that are a sustained sound rather than a hit: they fade in, and fade out with the screen
  const SUSTAINED = { humming: 900, dogs: 500, searchlight: 700, lorry: 600, ice_break: 400, paper: 150, pencil: 120, log_drag: 400 };
  // a single event, heard once when the text says so: never dropped in now and then by a soundscape
  const ONCE = new Set(['crying', 'prayer', 'humming', 'rail', 'shot', 'fight', 'raven', 'pat_down', 'log_drag']);
  const LOOP_AT = 0.15;                                // s: where a seamless file's loop starts (scripts/gen_sfx.py)
  let ambName = null, muff = 1;   // the body as a mixer: 1 is clear; see body()
  let queue = [], speakingId = 0, onDone = null;

  function el(loop) {
    const a = new Audio();
    a.loop = !!loop; a.preload = 'auto';
    a.onerror = () => { if (a.dataset.path) missing[a.dataset.path] = true; };
    return a;
  }
  function audioCtx() {
    if (web && !ctx) {
      // made on the first bed or the first click; before a click it waits, suspended, and unlock() resumes it
      ctx = new AudioContext();
      lowpass = ctx.createBiquadFilter(); lowpass.type = 'lowpass'; lowpass.frequency.value = 250 + Math.pow(muff, 2) * 18000;
      lowpass.connect(ctx.destination);
    }
    return ctx;
  }

  // ---------- beds: looping layers ----------
  // A bed looks like a media element to the code below (volume, paused, play, pause, _fade), so fades and
  // the soundscape logic treat both alike. With Web Audio: a buffer source that loops, through a gain.
  const buffers = new Map();          // path -> { p: Promise<AudioBuffer|null>, t: last used }
  function buffer(path) {
    let b = buffers.get(path);
    if (!b) {
      b = { p: fetch(path).then(r => { if (!r.ok) throw new Error(r.status); return r.arrayBuffer(); })
        .then(d => new Promise((ok, no) => ctx.decodeAudioData(d, ok, no)))
        .catch(() => { missing[path] = true; buffers.delete(path); return null; }) };
      buffers.set(path, b);
      // decoded beds are large (a 20 s stereo bed is about 7 MB); keep the most recent few
      if (buffers.size > 10) {
        const busy = new Set(beds.map(x => x.path));
        const old = [...buffers].filter(([k]) => !busy.has(k)).sort((x, y) => x[1].t - y[1].t)[0];
        if (old) buffers.delete(old[0]);
      }
    }
    b.t = performance.now();
    return b.p;
  }
  function bed() {
    const e = el(true);
    const b = {
      e, name: null, path: null, src: null, g: null, v: 0, playing: false, token: 0, _fade: 0, _level: 1,
      get _gain() { return !!ctx || !!e._gain; },     // the level is applied by a gain node, not the volume
      get volume() { return b.v; },
      set volume(v) {
        b.v = v;
        if (b.g) b.g.gain.value = v * b._level;
        e.volume = clamp(v, 0, 1);
      },
      get paused() { return !b.playing; },
      load(path, name) {
        if (b.path === path) return;
        b.pause(); b.path = path; b.name = name;
        if (!web) { e.dataset.path = path; e.src = path; }
      },
      // start somewhere in the loop, so the same bed does not begin the same way every time
      play(anywhere) {
        if (b.playing) return Promise.resolve();
        b.playing = true;
        const token = ++b.token, path = b.path;
        if (!audioCtx()) {
          const seek = () => { if (anywhere && e.duration && isFinite(e.duration)) e.currentTime = Math.random() * e.duration * 0.8; };
          if (e.readyState >= 1) seek(); else e.addEventListener('loadedmetadata', seek, { once: true });
          return e.play().catch(() => { b.playing = false; throw new Error('refused'); });
        }
        return buffer(path).then(buf => {
          if (token !== b.token) return;
          if (!buf) { b.playing = false; throw new Error('missing'); }
          const n = typeof LOOPS !== 'undefined' && LOOPS[b.name];
          const s = ctx.createBufferSource();
          s.buffer = buf; s.loop = true;
          let a = 0, z = buf.duration;
          if (n && LOOP_AT + n / 44100 <= buf.duration) { a = LOOP_AT; z = LOOP_AT + n / 44100; }
          s.loopStart = a; s.loopEnd = z;
          if (!b.g) { b.g = ctx.createGain(); b.g.connect(lowpass); }
          b.g.gain.value = b.v * b._level;
          s.connect(b.g);
          s.start(0, anywhere ? a + Math.random() * (z - a) * 0.8 : a);
          b.src = s;
        });
      },
      pause() {
        ++b.token; b.playing = false;
        if (b.src) { try { b.src.stop(); } catch (x) {} b.src.disconnect(); b.src = null; }
        if (!e.paused) e.pause();
      },
    };
    return b;
  }

  const ambs = [bed(), bed()]; let ambIdx = 0;          // two beds, alternating, for crossfades
  const sfx = Array.from({ length: 6 }, () => el(false)); let sfxIdx = 0;
  const voice = el(false);
  const pulse = bed();
  const layers = Array.from({ length: 6 }, () => bed());       // soundscape beds under the main ambience
  const spots = Array.from({ length: 4 }, () => el(false));     // soundscape one-shots, placed left or right
  const beds = [...ambs, pulse, ...layers];
  const all = [...beds.map(b => b.e), ...sfx, voice, ...spots];

  const levelOf = name => (typeof LEVELS !== 'undefined' && LEVELS[name]) || 1;
  function setLevel(a, name) {
    a._level = levelOf(name);
    if (a.g) a.g.gain.value = a.v * a._level;
    else if (a._gain && a._gain.gain) a._gain.gain.value = a._level;
  }
  // without Web Audio a level above 1 cannot be applied; a level below 1 can, through volume
  const vol = (a, v) => clamp(v * (a._gain ? 1 : Math.min(1, a._level || 1)), 0, 1);

  function unlock() {
    if (audioCtx() && !routed) {
      routed = true;
      all.forEach(a => {
        try {
          const g = ctx.createGain();
          g.gain.value = a._level || 1;
          ctx.createMediaElementSource(a).connect(g);
          if (ctx.createStereoPanner) { a._pan = ctx.createStereoPanner(); g.connect(a._pan); a._pan.connect(lowpass); }
          else g.connect(lowpass);
          a._gain = g;
        } catch (e) {}
      });
    }
    if (ctx && ctx.state === 'suspended') ctx.resume();
    restart();
  }
  function load(a, path, name) { setLevel(a, name); if (a.dataset.path !== path) { a.dataset.path = path; a.src = path; } }

  // Fades follow the ear, not the meter: in, the sound arrives slowly and then opens up;
  // out, it drops away at first and then lingers. A straight line in amplitude sounds abrupt.
  function fade(a, to, ms, then) {
    const from = a.volume, t0 = performance.now(), token = (a._fade = (a._fade || 0) + 1);
    const rising = to > from;
    (function step() {
      if (a._fade !== token) return;
      const k = Math.min(1, (performance.now() - t0) / ms);
      const e = rising ? Math.pow(k, 2.2) : 1 - Math.pow(1 - k, 2.2);
      a.volume = clamp(from + (to - from) * e, 0, 1);
      if (k < 1) requestAnimationFrame(step); else if (then) then();
    })();
  }
  // a new screen: let what the last one was saying trail off.
  // Sounds the text asks for play once per screen: the same screen shown again (the dev panel's fit check,
  // a refresh) plays nothing again, and a sound asked for twice on one screen is heard once.
  let screenObj = null, screenSounds = new Set(), replay = false;
  function scene(o) {
    replay = o === screenObj;
    if (replay) return;
    screenObj = o; screenSounds = new Set();
    if (!o.voice && !voice.paused) { ++speakingId; queue = []; finishVoice(); fade(voice, 0, 1200, () => voice.pause()); }
    for (const a of sfx) {
      if (a.paused || !a.duration) continue;
      if (a.duration - a.currentTime > 2.5) fade(a, 0, 1600, () => a.pause());
    }
  }
  // ---------- soundscapes ----------
  let scapeName = null, spotTimers = [], spotIdx = 0;
  const layerVol = a => on ? vol(a, AMB_VOL * a._lv * muff) : 0;
  function scape(name) {
    if (name === scapeName) return;
    scapeName = name;
    const spec = (typeof SCAPES !== 'undefined' && SCAPES[name]) || { beds: [], spots: [] };
    const want = new Map(spec.beds);
    // let go of the layers this place does not have
    for (const a of layers) if (a._layer && !want.has(a._layer)) {
      a._layer = null;
      fade(a, 0, AMB_OUT, () => { if (!a._layer) a.pause(); });
    }
    // bring in the ones it does
    for (const [file, lv] of want) {
      let a = layers.find(x => x._layer === file);
      if (!a) {
        const path = `assets/sfx/${file}.mp3`;
        if (missing[path]) continue;
        a = layers.find(x => !x._layer && x.paused) || layers.find(x => !x._layer);
        if (!a) continue;
        a._fade++;                                     // a fade-out still running on this layer ends here
        a._layer = file; setLevel(a, file); a.load(path, file); a.volume = 0;
      }
      a._lv = lv;
      if (on) a.play(true).then(() => { if (a._layer === file) fade(a, layerVol(a), AMB_IN); }).catch(() => {});
    }
    // and the sounds that come now and then
    spotTimers.forEach(clearTimeout); spotTimers = [];
    const list = spec.spots.map(([f, t, v]) => [[].concat(f).filter(x => !ONCE.has(x)), t, v]).filter(([f]) => f.length);
    list.forEach(([file, [lo, hi], v], i) => {
      const next = first => { spotTimers[i] = setTimeout(() => { if (scapeName === name) { spot(file, v); next(false); } }, (first ? lo * .5 + Math.random() * lo : lo + Math.random() * (hi - lo)) * 1000); };
      next(true);
    });
  }
  // file: a name, or a list to pick from (not the one heard last, when there is a choice)
  let lastSpot = null;
  function spot(file, v) {
    if (!on) return;
    if (Array.isArray(file)) {
      const pool = file.length > 1 ? file.filter(f => f !== lastSpot) : file;
      file = pool[Math.floor(Math.random() * pool.length)];
    }
    lastSpot = file;
    const path = `assets/sfx/${file}.mp3`;
    if (missing[path]) return;
    const a = spots[spotIdx]; spotIdx = (spotIdx + 1) % spots.length;
    a._fade = (a._fade || 0) + 1;
    load(a, path, file);
    if (a._pan) a._pan.pan.value = (Math.random() * 2 - 1) * .75;
    a.loop = false;
    a.volume = vol(a, SFX_VOL * v * (.4 + .6 * muff));
    a.currentTime = 0;
    a.play().catch(() => {});
  }

  // name: the main ambience; place: the soundscape, when the screen names one apart from its ambience
  function ambient(name, place) {
    scape(place || name);
    if (name === ambName) return;
    ambName = name;
    const old = ambs[ambIdx];
    fade(old, 0, AMB_OUT, () => old.pause());
    if (!name) return;
    const path = `assets/sfx/${name}.mp3`;
    if (missing[path]) return;
    ambIdx = 1 - ambIdx;
    const a = ambs[ambIdx];
    a._fade++;                                         // the fade-out of what this bed played before ends here
    setLevel(a, name); a.load(path, name);
    if (a.paused) a.volume = 0;
    if (on) a.play(true).then(() => { if (ambName === name && ambs[ambIdx] === a) fade(a, vol(a, AMB_VOL * muff), AMB_IN); }).catch(() => {});
  }
  // the beds that should be playing and are not: the sound was off (silent beds are not played at all),
  // or the browser refused to start them before the first click
  function restart() {
    if (!on) return;
    const a = ambs[ambIdx];
    if (ambName && a.paused && !missing[a.path]) a.play(true).then(() => { if (ambs[ambIdx] === a && a.name === ambName) fade(a, vol(a, AMB_VOL * muff), AMB_IN); }).catch(() => {});
    for (const l of layers) if (l._layer && l.paused && !missing[l.path]) l.play(true).then(() => { if (l._layer) fade(l, layerVol(l), AMB_IN); }).catch(() => {});
  }
  function snd(name) {
    if (!on || !name || replay || screenSounds.has(name)) return;
    screenSounds.add(name);
    const path = `assets/sfx/${name}.mp3`;
    if (missing[path]) return;
    const a = sfx[sfxIdx]; sfxIdx = (sfxIdx + 1) % sfx.length;
    a._fade = (a._fade || 0) + 1;   // cancel a fade-out still running on this slot
    load(a, path, name);
    a.loop = false;                 // a one-shot is heard once
    const target = vol(a, SFX_VOL * (0.4 + 0.6 * muff));
    a.currentTime = 0;
    if (SUSTAINED[name]) { a.volume = 0; a.play().then(() => fade(a, target, SUSTAINED[name])).catch(() => {}); }
    else { a.volume = target; a.play().catch(() => {}); }
  }

  // ---------- voice ----------
  // say(ids, done): plays the lines in order; done() is called once when they have all been heard,
  // or could not be (sound off, a file missing, playback refused), so the page never waits forever.
  function finishVoice() { const f = onDone; onDone = null; if (f) f(); }
  function say(ids, done) {
    finishVoice();
    onDone = done || null;
    queue = [].concat(ids || []).filter(Boolean);
    voice.pause();
    if (!on || !queue.length) return finishVoice();
    nextLine();
  }
  // The body in the voice: a line of the prisoner's has three takes (<id>, <id>_thin, <id>_going;
  // assets/manifest.json, voices.prisoner.states). The take follows the body; the plain one is the fallback.
  function take(id) {
    if (!/^prisoner_/.test(id) || typeof S === 'undefined' || !S) return null;
    const st = S.strength < 25 ? '_going' : S.strength < 45 ? '_thin' : '';
    return st && !missing[`assets/voice/${id}${st}.mp3`] ? id + st : null;
  }
  function nextLine() {
    if (!on || !queue.length) return finishVoice();
    let id = queue.shift(), alt = null;
    const t = take(id);
    if (t) { alt = id; id = t; }   // if the take is missing, the plain line follows
    // 'sfx:cough' in a voice list: a sound effect in its turn, after the words (the laugh, the cough)
    const path = id.startsWith('sfx:') ? `assets/sfx/${id.slice(4)}.mp3` : `assets/voice/${id}.mp3`;
    if (missing[path]) { if (alt) queue.unshift(alt); return nextLine(); }
    const token = ++speakingId;
    voice._fade = (voice._fade || 0) + 1;
    load(voice, path, 'voice');
    voice.volume = vol(voice, VOICE_VOL); voice.currentTime = 0;
    voice.onended = () => { if (speakingId === token) setTimeout(nextLine, 350); };
    voice.onerror = () => { missing[path] = true; if (alt) queue.unshift(alt); if (speakingId === token) nextLine(); };
    setTimeout(() => { if (speakingId === token) voice.play().catch(() => { if (speakingId === token) nextLine(); }); }, 400);
  }
  const speaking = () => !!onDone;

  // the body as a mixer: as strength drops the world muffles and a pulse comes up
  const PULSE = 'assets/sfx/pulse.mp3';
  function body(strength) {
    muff = clamp((strength - 5) / 35, 0.2, 1);   // clear above 40; by 20 the world is through a wall; at 10 a pulse and a blanket
    if (lowpass) lowpass.frequency.setTargetAtTime(250 + Math.pow(muff, 2) * 18000, ctx.currentTime, 0.8);
    const a = ambs[ambIdx];
    if (ambName && !a.paused) a.volume = on ? Math.min(a.volume, vol(a, AMB_VOL * muff)) : 0;
    for (const l of layers) if (l._layer && !l.paused) l.volume = Math.min(l.volume, layerVol(l));
    const wantPulse = strength < 25 && !missing[PULSE];
    if (wantPulse) {
      setLevel(pulse, 'pulse'); pulse.load(PULSE, 'pulse');
      const target = on ? vol(pulse, clamp((25 - strength) / 25, 0, 1) * 0.7) : 0;
      if (pulse.paused) { if (on) { pulse.volume = 0; pulse._fade++; pulse.play(false).then(() => fade(pulse, target, 2500)).catch(() => {}); } }
      else if (pulse._out) { pulse._out = false; fade(pulse, target, 1000); }
      else pulse.volume = target;
    } else if (!pulse.paused && !pulse._out) { pulse._out = true; fade(pulse, 0, 1500, () => { pulse._out = false; pulse.pause(); }); }
  }
  function toggle() {
    on = !on;
    if (!testing) try { localStorage.setItem('ten-years-sound', on ? 'on' : 'off'); } catch (e) {}
    ambs.forEach(a => {
      a._fade++;
      if (a === ambs[ambIdx] && ambName) a.volume = on ? vol(a, AMB_VOL * muff) : 0;
      else { a.volume = 0; a.pause(); }
    });
    layers.forEach(l => { l._fade++; if (l._layer) l.volume = layerVol(l); else { l.volume = 0; l.pause(); } });
    if (!on) { voice.pause(); queue = []; finishVoice(); pulse._out = false; pulse.pause(); }
    restart();
    return on;
  }
  document.addEventListener('pointerdown', unlock, { once: true });
  document.addEventListener('keydown', unlock, { once: true });
  // the dev panel calls this: silence the page for testing, without saving it as the player's choice
  function testMode() {
    testing = true;
    if (on && !/[?&]sound\b/.test(location.search)) toggle();
  }
  const bedState = b => ({ name: b.name, playing: b.playing, web: !!b.src, loop: b.src ? [+b.src.loopStart.toFixed(3), +b.src.loopEnd.toFixed(3)] : null, volume: +b.v.toFixed(3) });
  const state = () => ({
    main: ambName, scape: scapeName, ctx: ctx ? ctx.state : null,
    layers: layers.filter(l => l._layer).map(l => `${l._layer}${l.paused ? ' (paused)' : ''}`), spots: spotTimers.length,
    beds: beds.filter(b => b.name).map(bedState),
    oneShots: sfx.filter(a => !a.paused).map(a => ({ path: a.dataset.path, loop: a.loop })),
    decoded: buffers.size,
  });
  return { ambient, snd, spot, say, body, scene, toggle, unlock, speaking, testMode, state, isOn: () => on };
})();
